def output(name,replacements):
 original=(OLD/name).read_text();result=original
 for old,new in replacements:
  if old.startswith('ALLTEST:'):
   old=old[8:]
   if result.count(old)!=3:raise RuntimeError('Expected exactly three recorder session seams')
  elif old.startswith('ALL:'):
   old=old[4:]
   if result.count(old)!=4:raise RuntimeError('Expected exactly four loader path seams')
  elif result.count(old)!=1:raise RuntimeError(f'Expected one seam in {name}: {old!r}; got {result.count(old)}')
  result=result.replace(old,new)
 return original,result
