 entries=[];patch=[]
 for name,destination,replacements in SPECS:
  original,result=output(name,replacements);target=ROOT/destination
  if args.check:
   if target.read_text()!=result:raise RuntimeError('Derived bytes differ: '+destination)
  else:
   with target.open('w' if args.refresh else 'x') as f:f.write(result)
  entries.append({'source':str((OLD/name).relative_to(REPO)),'destination':str(target.relative_to(REPO)),'sourceSha256':hashlib.sha256(original.encode()).hexdigest(),'derivedSha256':hashlib.sha256(result.encode()).hexdigest(),'replacements':[{'old':a,'new':b} for a,b in replacements]})
  patch.extend(difflib.unified_diff(original.splitlines(True),result.splitlines(True),fromfile=str((OLD/name).relative_to(REPO)),tofile=str(target.relative_to(REPO))))
